CREATE TABLE projection_policy(singleton INTEGER PRIMARY KEY CHECK(singleton=1),projection_schema TEXT NOT NULL CHECK(projection_schema='ergentics_disposal_evidence_v1'),authority_vector TEXT NOT NULL CHECK(authority_vector='00000000'),authoritative INTEGER NOT NULL CHECK(authoritative=0),may_feed_controller INTEGER NOT NULL CHECK(may_feed_controller=0),prose_may_supply_fact INTEGER NOT NULL CHECK(prose_may_supply_fact=0),unavailable_behavior TEXT NOT NULL CHECK(unavailable_behavior='EMPTY_OR_EXPLICIT_ABSTAIN_NO_STALE_FALLBACK')) STRICT;
CREATE TABLE input_artifacts(artifact_id TEXT PRIMARY KEY CHECK(length(artifact_id)=64),artifact_role TEXT NOT NULL CHECK(artifact_role IN('CANONICAL_LEDGER_PREFIX','DISPOSAL_JOURNAL','RETAINED_JOURNAL_LEAF','RETAINED_STDIO_RECEIPT','OBSERVABILITY_JOURNAL','OBSERVABILITY_DATABASE','CPU_OVERLAY_JOURNAL','CPU_OVERLAY_DATABASE','IMPLEMENTATION_SOURCE')),logical_path TEXT NOT NULL,availability TEXT NOT NULL CHECK(availability IN('PRESENT_HELD','LEDGER_EMBEDDED_COPY')),admission_grade TEXT NOT NULL CHECK(admission_grade IN('HELD_VNODE_HASH_EXACT','CANONICAL_LEDGER_FRAME_EXACT','CANONICAL_JOURNAL_FRAME_EXACT','STATIC_SOURCE_ONLY_NOT_OPERATIONAL_EVIDENCE')),device_text TEXT,inode_text TEXT,generation_text TEXT,uid INTEGER,gid INTEGER,mode_text TEXT,nlink INTEGER,byte_count INTEGER NOT NULL CHECK(byte_count>0),raw_sha256 TEXT NOT NULL CHECK(length(raw_sha256)=64),raw_bytes BLOB NOT NULL CHECK(length(raw_bytes)=byte_count),CHECK((availability='PRESENT_HELD' AND device_text IS NOT NULL AND inode_text IS NOT NULL AND uid IS NOT NULL AND gid IS NOT NULL AND mode_text IS NOT NULL AND nlink=1) OR (availability='LEDGER_EMBEDDED_COPY' AND device_text IS NULL AND inode_text IS NULL AND generation_text IS NULL AND uid IS NULL AND gid IS NULL AND mode_text IS NULL AND nlink IS NULL))) STRICT,WITHOUT ROWID;
CREATE TABLE invocations(invocation_id TEXT PRIMARY KEY CHECK(length(invocation_id)=64),arc_label TEXT NOT NULL,epoch_label TEXT NOT NULL,source_artifact_id TEXT NOT NULL REFERENCES input_artifacts(artifact_id),control_commit TEXT CHECK(control_commit IS NULL OR length(control_commit)=40),control_tree TEXT CHECK(control_tree IS NULL OR length(control_tree)=40),implementation_commit TEXT CHECK(implementation_commit IS NULL OR length(implementation_commit)=40),implementation_tree TEXT CHECK(implementation_tree IS NULL OR length(implementation_tree)=40),consumption_state TEXT NOT NULL CHECK(consumption_state IN('UNCONSUMED','CONSUMED_SOURCE_DECLARED','ABSTAIN_NOT_RECORDED')),retry_authorized INTEGER NOT NULL CHECK(retry_authorized=0),authority_vector TEXT NOT NULL CHECK(authority_vector='00000000')) STRICT,WITHOUT ROWID;
CREATE TABLE missing_evidence(missing_id TEXT PRIMARY KEY CHECK(length(missing_id)=64),invocation_id TEXT NOT NULL REFERENCES invocations(invocation_id),evidence_kind TEXT NOT NULL,target_role TEXT,source_frame_id TEXT REFERENCES frames(frame_id),reason_code TEXT NOT NULL,value_state TEXT NOT NULL CHECK(value_state='ABSTAIN'),evidence_scope TEXT NOT NULL CHECK(evidence_scope IN('FRAME_PREFIX','PROJECTION_GLOBAL_NON_PREFIX')),CHECK((evidence_scope='FRAME_PREFIX' AND source_frame_id IS NOT NULL) OR (evidence_scope='PROJECTION_GLOBAL_NON_PREFIX' AND source_frame_id IS NULL))) STRICT,WITHOUT ROWID;
CREATE TABLE streams(stream_id TEXT PRIMARY KEY CHECK(length(stream_id)=64),invocation_id TEXT REFERENCES invocations(invocation_id),source_artifact_id TEXT NOT NULL REFERENCES input_artifacts(artifact_id),stream_kind TEXT NOT NULL CHECK(stream_kind IN('CANONICAL_LEDGER','DISPOSAL_JOURNAL','STDOUT_RECEIPT','STDERR_RECEIPT','OBSERVABILITY','CPU_OVERLAY')),completeness TEXT NOT NULL CHECK(completeness IN('COMPLETE_SEALED','RETAINED_PREFIX_NONTERMINAL','SINGLE_RECEIPT','ABSTAIN_INCOMPLETE')),stream_sha256 TEXT NOT NULL CHECK(length(stream_sha256)=64),stream_bytes INTEGER NOT NULL CHECK(stream_bytes>0)) STRICT,WITHOUT ROWID;
CREATE TABLE frames(frame_id TEXT PRIMARY KEY CHECK(length(frame_id)=64),stream_id TEXT NOT NULL REFERENCES streams(stream_id),source_artifact_id TEXT NOT NULL REFERENCES input_artifacts(artifact_id),ordinal INTEGER NOT NULL CHECK(ordinal>=0),previous_frame_id TEXT REFERENCES frames(frame_id),source_leaf TEXT,byte_offset INTEGER NOT NULL CHECK(byte_offset>=0),byte_count INTEGER NOT NULL CHECK(byte_count>1),terminal_lf INTEGER NOT NULL CHECK(terminal_lf IN(0,1)),raw_json BLOB NOT NULL CHECK(length(raw_json)=byte_count),raw_sha256_no_lf TEXT NOT NULL CHECK(length(raw_sha256_no_lf)=64),raw_sha256_with_lf TEXT CHECK(raw_sha256_with_lf IS NULL OR length(raw_sha256_with_lf)=64),canonical_json_sha256 TEXT NOT NULL CHECK(length(canonical_json_sha256)=64),payload_sha256 TEXT CHECK(payload_sha256 IS NULL OR length(payload_sha256)=64),schema_text TEXT NOT NULL,status_text TEXT,UNIQUE(stream_id,ordinal),UNIQUE(stream_id,byte_offset),CHECK((ordinal=0 AND previous_frame_id IS NULL) OR (ordinal>0 AND previous_frame_id IS NOT NULL))) STRICT,WITHOUT ROWID;
CREATE TABLE frame_adapter_coverage(frame_id TEXT PRIMARY KEY REFERENCES frames(frame_id),payload_schema TEXT NOT NULL,event_type TEXT NOT NULL CHECK(event_type IN('start','clocks','policy','snapshot','namespace','resource','commitment','signal_call','wait_reap','absence','conservation','risk_window','terminal')),adapter_state TEXT NOT NULL CHECK(adapter_state IN('KNOWN_TYPED','KNOWN_NO_PROCESS_FACTS','UNKNOWN_RAW_ONLY')),operational_scope TEXT NOT NULL CHECK(operational_scope IN('LIFECYCLE','NON_LIFECYCLE')),adapter_manifest_sha256 TEXT NOT NULL CHECK(length(adapter_manifest_sha256)=64)) STRICT,WITHOUT ROWID;
