CREATE TABLE targets(target_id TEXT PRIMARY KEY CHECK(length(target_id)=64),invocation_id TEXT NOT NULL REFERENCES invocations(invocation_id),target_role TEXT NOT NULL CHECK(target_role IN('DISPOSAL_CONTROLLER','GATE_C_WRAPPER','GATE_C_AWK','R19_WAIT_WRAPPER','R19_GUARDIAN','R19_FIXTURE','CONTROLLER','GUARDIAN','FIXTURE','ASSESSMENT','WRAPPER','OBSERVER','PRIVATE_CHILD')),numeric_pid INTEGER NOT NULL CHECK(numeric_pid>1),target_form TEXT NOT NULL CHECK(target_form IN('POSITIVE_PID','NEGATIVE_PGID','OBSERVATION_ONLY')),expected_uniqueid_text TEXT,expected_idversion_text TEXT,expected_parent_uniqueid_text TEXT,expected_parent_idversion_text TEXT,expected_sid INTEGER CHECK(expected_sid IS NULL OR expected_sid>1),expected_pgid INTEGER CHECK(expected_pgid IS NULL OR expected_pgid>1),expected_uuid_hex TEXT CHECK(expected_uuid_hex IS NULL OR length(expected_uuid_hex)=32),expected_uid INTEGER,expected_gid INTEGER,expected_image_artifact_id TEXT REFERENCES input_artifacts(artifact_id),expected_cwd_artifact_id TEXT REFERENCES input_artifacts(artifact_id),UNIQUE(invocation_id,target_role,numeric_pid)) STRICT,WITHOUT ROWID;
