CREATE TABLE domain_members(domain_snapshot_id TEXT NOT NULL REFERENCES domain_snapshots(domain_snapshot_id),member_ordinal INTEGER NOT NULL CHECK(member_ordinal>=0),receipt_id TEXT NOT NULL REFERENCES process_receipts(receipt_id),PRIMARY KEY(domain_snapshot_id,member_ordinal),UNIQUE(domain_snapshot_id,receipt_id)) STRICT,WITHOUT ROWID;
CREATE TABLE target_snapshots(snapshot_id TEXT PRIMARY KEY CHECK(length(snapshot_id)=64),source_frame_id TEXT NOT NULL REFERENCES frames(frame_id),target_id TEXT NOT NULL REFERENCES targets(target_id),snapshot_phase TEXT NOT NULL CHECK(snapshot_phase IN('PRESTATE','PRECOMMIT_FIRST','PRECOMMIT_SECOND','POSTCOMMIT_FIRST','POSTCOMMIT_SECOND','STOPPED_FIXED_POINT','POSTCALL','ABSENCE')),snapshot_kind TEXT NOT NULL CHECK(snapshot_kind IN('PRESENT','ABSENT','REBOUND','UNKNOWN')),receipt_id TEXT REFERENCES process_receipts(receipt_id),image_join_id TEXT REFERENCES vnode_joins(join_id),cwd_join_id TEXT REFERENCES vnode_joins(join_id),group_snapshot_id TEXT REFERENCES domain_snapshots(domain_snapshot_id),session_snapshot_id TEXT REFERENCES domain_snapshots(domain_snapshot_id),snapshot_sha256 TEXT NOT NULL CHECK(length(snapshot_sha256)=64)) STRICT,WITHOUT ROWID;
