CREATE TABLE conservation_set_conservation_states(conservation_id TEXT PRIMARY KEY REFERENCES conservations(conservation_id),source_frame_id TEXT NOT NULL REFERENCES frames(frame_id),conservation_set_commitment_id TEXT REFERENCES conservation_set_commitments(conservation_set_commitment_id),merkle_state TEXT NOT NULL CHECK(merkle_state IN('VERIFIED_PRIOR_EXACT','ABSENT_UNKNOWN')),CHECK((merkle_state='VERIFIED_PRIOR_EXACT' AND conservation_set_commitment_id IS NOT NULL) OR (merkle_state='ABSENT_UNKNOWN' AND conservation_set_commitment_id IS NULL))) STRICT,WITHOUT ROWID;
CREATE TABLE conservation_set_obligation_mappings(mapping_id TEXT PRIMARY KEY CHECK(length(mapping_id)=64),conservation_id TEXT NOT NULL REFERENCES conservations(conservation_id),conservation_set_commitment_id TEXT NOT NULL REFERENCES conservation_set_commitments(conservation_set_commitment_id),membership_id TEXT NOT NULL UNIQUE REFERENCES conservation_set_memberships(membership_id),target_id TEXT NOT NULL REFERENCES targets(target_id),mapping_state TEXT NOT NULL CHECK(mapping_state='EXPLICIT_SAME_GENERATION'),UNIQUE(conservation_id,membership_id)) STRICT,WITHOUT ROWID;
CREATE TABLE risk_windows(window_id TEXT PRIMARY KEY CHECK(length(window_id)=64),source_frame_id TEXT NOT NULL REFERENCES frames(frame_id),target_id TEXT REFERENCES targets(target_id),window_kind TEXT NOT NULL CHECK(window_kind IN('SOURCE_REALPATH_TO_DESCRIPTOR_OPEN','TERMINAL_NAMESPACE_TO_SIGNAL_ENTRY','JOINED_SNAPSHOT_TO_NUMERIC_PID','SINGLETON_SNAPSHOT_TO_NUMERIC_PGID','GROUP_SNAPSHOT_TO_LATE_MEMBER_OR_REUSE','SNAPSHOT_PAIR_GAP','CERTIFICATE_TO_CALL_ENTRY','SIGNAL_RETURN_TO_RESULT_PUBLICATION','RESULT_TO_CONSERVATION_PUBLICATION','WAIT_RETURN_TO_REAP_PUBLICATION','GENERATION_DOMAIN_TO_SIGNAL_ZERO','RUSAGE_SAMPLE_INTERVAL','HELD_DESCRIPTOR_TO_NAMED_JOIN','SAME_UID_POSTJOIN_REPLACEMENT_ABA')),start_frame_id TEXT REFERENCES frames(frame_id),end_frame_id TEXT REFERENCES frames(frame_id),commitment_id TEXT REFERENCES commitments(commitment_id),signal_call_id TEXT REFERENCES signal_calls(signal_call_id),maximum_duration_ns_text TEXT,basis TEXT NOT NULL CHECK(basis IN('SOURCE_DECLARED','EVENT_ORDER_DERIVED','HELD_DESCRIPTOR_JOIN','ABSTAIN_UNAVAILABLE')),closure_state TEXT NOT NULL CHECK(closure_state IN('KERNEL_EXCLUDED','HELD_DESCRIPTOR_POSTJOIN_DETECTABLE','BOUNDED_USERSPACE_RESIDUAL','UNBOUNDED_NAMED_RESIDUAL','UNKNOWN')),qualification_text TEXT NOT NULL) STRICT,WITHOUT ROWID;
CREATE TABLE terminal_outcomes(terminal_outcome_id TEXT PRIMARY KEY CHECK(length(terminal_outcome_id)=64),invocation_id TEXT NOT NULL UNIQUE REFERENCES invocations(invocation_id),terminal_frame_id TEXT NOT NULL UNIQUE REFERENCES frames(frame_id),status_text TEXT NOT NULL,exit_code INTEGER,capture_state TEXT NOT NULL CHECK(capture_state IN('EXACT_RETAINED','EMPTY_RETAINED','ABSENT','ABSTAIN')),gate_c_conservation_id TEXT REFERENCES conservations(conservation_id),guardian_conservation_id TEXT REFERENCES conservations(conservation_id),wrapper_conservation_id TEXT REFERENCES conservations(conservation_id),fixture_conservation_id TEXT REFERENCES conservations(conservation_id),completion_class TEXT NOT NULL CHECK(completion_class IN('NOOP_ALREADY_CONSERVED','DEFERRED_TERMINAL_APPEARED','PREACTUATION_REJECTED','CONSERVATION_COMPLETE','SIGNAL_ENTERED_NONTERMINAL','PREFIX_INTERRUPTED','ABSTAIN_INCOMPLETE')),authority_vector TEXT NOT NULL CHECK(authority_vector='00000000'),gate_e_outcome TEXT NOT NULL CHECK(gate_e_outcome='ABSTAIN')) STRICT,WITHOUT ROWID;
CREATE TABLE evidence_seal(singleton INTEGER PRIMARY KEY CHECK(singleton=1),projection_id TEXT NOT NULL CHECK(length(projection_id)=64),predecessor_projection_id TEXT CHECK(predecessor_projection_id IS NULL OR length(predecessor_projection_id)=64),input_inventory_sha256 TEXT NOT NULL CHECK(length(input_inventory_sha256)=64),ddl_sha256 TEXT NOT NULL CHECK(length(ddl_sha256)=64),adapter_sha256 TEXT NOT NULL CHECK(length(adapter_sha256)=64),extractor_sha256 TEXT NOT NULL CHECK(length(extractor_sha256)=64),lattice_sha256 TEXT NOT NULL CHECK(length(lattice_sha256)=64),relational_export_sha256 TEXT NOT NULL CHECK(length(relational_export_sha256)=64),high_water_frame_id TEXT REFERENCES frames(frame_id),artifact_count INTEGER NOT NULL CHECK(artifact_count>=0),invocation_count INTEGER NOT NULL CHECK(invocation_count>=0),frame_count INTEGER NOT NULL CHECK(frame_count>=0),frame_adapter_coverage_count INTEGER NOT NULL CHECK(frame_adapter_coverage_count>=0),target_count INTEGER NOT NULL CHECK(target_count>=0),target_provenance_count INTEGER NOT NULL CHECK(target_provenance_count>=0),commitment_count INTEGER NOT NULL CHECK(commitment_count>=0),signal_call_count INTEGER NOT NULL CHECK(signal_call_count>=0),wait_call_count INTEGER NOT NULL CHECK(wait_call_count>=0),conservation_count INTEGER NOT NULL CHECK(conservation_count>=0),conservation_set_commitment_count INTEGER NOT NULL CHECK(conservation_set_commitment_count>=0),conservation_set_membership_count INTEGER NOT NULL CHECK(conservation_set_membership_count>=0),conservation_set_mapping_count INTEGER NOT NULL CHECK(conservation_set_mapping_count>=0),risk_window_count INTEGER NOT NULL CHECK(risk_window_count>=0),missing_evidence_count INTEGER NOT NULL CHECK(missing_evidence_count>=0),authority_vector TEXT NOT NULL CHECK(authority_vector='00000000'),authoritative INTEGER NOT NULL CHECK(authoritative=0),may_feed_controller INTEGER NOT NULL CHECK(may_feed_controller=0),CHECK(frame_adapter_coverage_count=frame_count),CHECK(target_provenance_count=target_count)) STRICT;
CREATE VIEW presentation_authority_boundary AS SELECT authority_vector,authoritative,may_feed_controller,prose_may_supply_fact,unavailable_behavior FROM projection_policy WHERE singleton=1;
CREATE VIEW commitment_obligation_projection AS SELECT c.commitment_id,c.target_id,c.operation,c.numeric_argument,CASE WHEN m.membership_id IS NULL THEN 'ABSTAIN' WHEN co.completion_state='COMPLETE' AND cs.merkle_state='VERIFIED_PRIOR_EXACT' THEN 'CONSERVED' WHEN s.signal_call_id IS NULL THEN 'MAY_HAVE_ENTERED' WHEN s.entry_state IN('ENTERED','MAY_HAVE_ENTERED') THEN 'CONTAINMENT_REQUIRED' ELSE 'ABSTAIN' END AS obligation_state FROM commitments c LEFT JOIN conservation_set_memberships m ON m.obligation_commitment_id=c.commitment_id LEFT JOIN conservation_set_obligation_mappings om ON om.membership_id=m.membership_id AND om.conservation_set_commitment_id=m.conservation_set_commitment_id LEFT JOIN conservation_set_conservation_states cs ON cs.conservation_id=om.conservation_id AND cs.conservation_set_commitment_id=m.conservation_set_commitment_id AND cs.merkle_state='VERIFIED_PRIOR_EXACT' LEFT JOIN conservations co ON co.conservation_id=om.conservation_id AND co.target_id=c.target_id LEFT JOIN signal_calls s ON s.commitment_id=c.commitment_id;
