CREATE TRIGGER conservation_set_memberships_exact_obligation_join BEFORE INSERT ON conservation_set_memberships WHEN NOT EXISTS(SELECT 1 FROM conservation_set_commitments s JOIN frames sf ON sf.frame_id=s.source_frame_id JOIN commitments c ON c.commitment_id=NEW.obligation_commitment_id JOIN frames cf ON cf.frame_id=c.source_frame_id JOIN targets t ON t.target_id=c.target_id WHERE s.conservation_set_commitment_id=NEW.conservation_set_commitment_id AND t.invocation_id=s.invocation_id AND cf.stream_id=sf.stream_id AND cf.ordinal<sf.ordinal AND c.target_id=NEW.target_id AND t.target_role=NEW.target_role AND t.target_form=NEW.target_form AND t.expected_uniqueid_text=NEW.expected_uniqueid_text AND t.expected_idversion_text=NEW.expected_idversion_text AND c.operation=NEW.operation AND c.numeric_argument=NEW.numeric_argument AND c.signal_number=NEW.signal_number AND c.budget_ordinal=NEW.budget_ordinal AND c.source_frame_id=NEW.commitment_source_frame_id AND cf.raw_sha256_with_lf=NEW.commitment_frame_lf_sha256) BEGIN SELECT RAISE(ABORT,'merkle-membership-obligation-join'); END;
