CREATE TRIGGER conservation_set_conservation_states_temporal_join BEFORE INSERT ON conservation_set_conservation_states WHEN NEW.merkle_state='VERIFIED_PRIOR_EXACT' AND NOT EXISTS(SELECT 1 FROM conservations c JOIN frames cf ON cf.frame_id=c.source_frame_id JOIN conservation_set_commitments s ON s.conservation_set_commitment_id=NEW.conservation_set_commitment_id JOIN frames sf ON sf.frame_id=s.source_frame_id WHERE c.conservation_id=NEW.conservation_id AND sf.stream_id=cf.stream_id AND sf.ordinal<cf.ordinal) BEGIN SELECT RAISE(ABORT,'merkle-conservation-temporal-join'); END;
