CREATE TRIGGER conservation_set_obligation_mappings_exact_join BEFORE INSERT ON conservation_set_obligation_mappings WHEN NOT EXISTS(SELECT 1 FROM conservation_set_memberships m JOIN conservations c ON c.conservation_id=NEW.conservation_id JOIN conservation_set_conservation_states s ON s.conservation_id=c.conservation_id WHERE m.membership_id=NEW.membership_id AND m.conservation_set_commitment_id=NEW.conservation_set_commitment_id AND m.target_id=NEW.target_id AND c.target_id=NEW.target_id AND s.merkle_state='VERIFIED_PRIOR_EXACT' AND s.conservation_set_commitment_id=NEW.conservation_set_commitment_id AND s.source_frame_id=c.source_frame_id) BEGIN SELECT RAISE(ABORT,'merkle-mapping-exact-join'); END;
