CREATE TRIGGER evidence_seal_merkle_membership_cardinality BEFORE INSERT ON evidence_seal WHEN EXISTS(SELECT 1 FROM conservation_set_commitments s WHERE s.leaf_count<>(SELECT count(*) FROM conservation_set_memberships m WHERE m.conservation_set_commitment_id=s.conservation_set_commitment_id) OR s.leaf_count<>(SELECT count(*) FROM commitments c JOIN targets t ON t.target_id=c.target_id WHERE t.invocation_id=s.invocation_id)) BEGIN SELECT RAISE(ABORT,'merkle-full-obligation-set'); END;
CREATE TRIGGER evidence_seal_merkle_proof_cardinality BEFORE INSERT ON evidence_seal WHEN EXISTS(SELECT 1 FROM conservation_set_memberships m WHERE m.proof_depth<>(SELECT count(*) FROM conservation_set_membership_proof_nodes p WHERE p.membership_id=m.membership_id) OR (m.proof_depth>0 AND (SELECT max(p.proof_ordinal) FROM conservation_set_membership_proof_nodes p WHERE p.membership_id=m.membership_id)<>m.proof_depth-1)) BEGIN SELECT RAISE(ABORT,'merkle-proof-cardinality'); END;
CREATE TRIGGER evidence_seal_merkle_conservation_state_total BEFORE INSERT ON evidence_seal WHEN EXISTS(SELECT 1 FROM conservations c LEFT JOIN conservation_set_conservation_states s ON s.conservation_id=c.conservation_id WHERE s.conservation_id IS NULL) BEGIN SELECT RAISE(ABORT,'merkle-conservation-state-missing'); END;
CREATE TRIGGER evidence_seal_merkle_mapping_total BEFORE INSERT ON evidence_seal WHEN EXISTS(SELECT 1 FROM conservation_set_conservation_states s WHERE (s.merkle_state='VERIFIED_PRIOR_EXACT' AND NOT EXISTS(SELECT 1 FROM conservation_set_obligation_mappings m WHERE m.conservation_id=s.conservation_id AND m.conservation_set_commitment_id=s.conservation_set_commitment_id)) OR (s.merkle_state='ABSENT_UNKNOWN' AND EXISTS(SELECT 1 FROM conservation_set_obligation_mappings m WHERE m.conservation_id=s.conservation_id))) BEGIN SELECT RAISE(ABORT,'merkle-conservation-mapping-state'); END;
